import { inject, Injectable } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';
import { Tag, Verse } from '../common/verse/verse';
import { WidgetSyncService } from '../common/widget/widget-sync.service';

@Injectable({
  providedIn: 'root',
})
export class FavoritesService {
  private supabaseClient = inject(SupabaseClient<Database>);
  private widgetSyncService = inject(WidgetSyncService);

  async getFavorites(): Promise<Verse[]> {
    // Use the original edge function approach that was working
    const { data } = await this.supabaseClient.functions.invoke('verses', {
      method: 'GET',
    });

    const verses = ((data?.verses || []) as Verse[]).filter(
      (verse) => verse.is_favorite
    );

    if (verses.length === 0) {
      return [];
    }

    // Fetch all verse_tags for these verses
    const verseIds = verses.map((v) => v.id);
    const { data: verseTags } = await this.supabaseClient
      .from('verse_tags')
      .select('verse_id, tags(*)')
      .in('verse_id', verseIds);

    // Create a map of verse_id to tags
    const tagsByVerseId = new Map<number, Tag[]>();
    if (verseTags) {
      for (const vt of verseTags) {
        const existing: Tag[] = tagsByVerseId.get(vt.verse_id) || [];
        if (vt.tags) {
          // Handle both single object and array cases
          const tags = Array.isArray(vt.tags) ? vt.tags : [vt.tags];
          existing.push(...(tags as Tag[]));
        }
        tagsByVerseId.set(vt.verse_id, existing);
      }
    }

    // Merge tags into verses
    return verses.map((verse) => ({
      ...verse,
      tags: tagsByVerseId.get(verse.id!) || [],
    }));
  }

  async getUserTags(): Promise<Tag[]> {
    const { data, error } = await this.supabaseClient
      .from('tags')
      .select('*')
      .order('name', { ascending: true });

    if (error || !data) {
      return [];
    }

    return data as Tag[];
  }

  /**
   * Sync current favorites to the iOS widget.
   * Fetches fresh favorites and syncs them to widget storage.
   */
  async syncToWidget(): Promise<void> {
    const favorites = await this.getFavorites();
    await this.widgetSyncService.syncFavorites(favorites);
  }
}
